import { costs } from "./costs";

const LEDGER = "https://github.com/founder2863/01scale.com/blob/main/docs/process/token-ledger.json";

function mtok(value: number) {
  return `${(value / 1_000_000).toFixed(1)}M`;
}

function usd(value: number) {
  return `$${value.toFixed(2)}`;
}

function percent(part: number, whole: number) {
  return whole > 0 ? Math.round((100 * part) / whole) : 0;
}

// The token yield formula on one line; selecting it opens how the number is worked out
// (story MVP1-E0-17). Every number comes from costs.ts, generated by `npm run costs`.
export default function YieldExplainer() {
  // The worked example is the story with the most rework, so the formula is shown doing real work.
  const example = [...costs.stories]
    .filter((story) => story.buildTokens > 0 && story.reworkTokens > 0)
    .sort((a, b) => b.reworkTokens - a.reworkTokens)[0];

  return (
    <details className="yield-explainer">
      <summary>
        <span className="yield-formula">
          Token yield = build ÷ (build + rework)
        </span>
        <span className="yield-hint">How is this calculated?</span>
      </summary>

      <div className="yield-body">
        <p>
          Measured in tokens: a story&apos;s build tokens divided by its build plus rework
          tokens, so token yield is the share of its tokens that went into work kept the first
          time. <strong>100%</strong> means nothing on that story had to be redone;{" "}
          <strong>50%</strong> means half its tokens went into changing or fixing earlier work.
        </p>

        <ol className="yield-steps">
          <li>
            <strong>Measure.</strong> Every token of every request is read from the Claude Code
            session record: input, output, and reads and writes to the model&apos;s cache. Nothing
            is estimated or typed in by hand.
          </li>
          <li>
            <strong>Classify.</strong> Each request is labelled against a story as{" "}
            <em>build</em> (produced something that was kept), <em>rework</em> (changed or fixed
            something already delivered, because a decision changed, a review found a problem or a
            mistake was fixed) or <em>scaffolding</em> (tied to no story: questions, discovery,
            tooling, process). Scaffolding is left out of a story&apos;s yield.
          </li>
          <li>
            <strong>Compute.</strong> For each story, build tokens ÷ (build + rework tokens), then
            the same across all stories.
          </li>
        </ol>

        {example && (
          <p className="yield-example">
            <strong>Example: {example.name}.</strong> {mtok(example.buildTokens)} build tokens and{" "}
            {mtok(example.reworkTokens)} rework tokens give{" "}
            {mtok(example.buildTokens)} ÷ ({mtok(example.buildTokens)} +{" "}
            {mtok(example.reworkTokens)}) = <strong>{example.yield}%</strong>. On cost instead of
            tokens it is {usd(example.buildCost)} ÷ ({usd(example.buildCost)} +{" "}
            {usd(example.reworkCost)}) ={" "}
            {percent(example.buildCost, example.buildCost + example.reworkCost)}%.
          </p>
        )}

        <p>
          <strong>The two totals:</strong> token yield across stories is{" "}
          {costs.totals.storyYield}% (the same formula over all stories), and{" "}
          {costs.totals.overallYield}% of all tokens went into kept story work once scaffolding is
          included.
        </p>

        <ul className="yield-caveats">
          <li>
            Yield is on tokens, not dollars. Most tokens are cheap re-reads of the conversation
            from the cache, so a yield on cost can come out quite differently, as the example
            shows.
          </li>
          <li>
            The build, rework and scaffolding labels are my judgement, listed request by request
            in the <a href={LEDGER}>ledger</a>.
          </li>
          <li>
            A request sent after a break of more than an hour carries the cost of reloading the
            whole conversation.
          </li>
          <li>
            A low yield means a decision changed after work was done, not that the work was poor.
            Changing your mind after design is cheaper than after code, but it is not free.
          </li>
        </ul>
      </div>
    </details>
  );
}
